CREATE EXTENSION IF NOT EXISTS pg_cron;
CREATE FUNCTION private.financeiro_rotina_mensal() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE mes date=date_trunc('month',now() AT TIME ZONE 'America/Sao_Paulo')::date; BEGIN PERFORM pg_advisory_xact_lock(81722,1);IF NOT EXISTS(SELECT 1 FROM public.financeiro_config WHERE id AND automatico) THEN RETURN 0;END IF;PERFORM private.financeiro_travar_data(mes);RETURN private.financeiro_gerar_mes(mes);END; $$;
REVOKE ALL ON FUNCTION private.financeiro_rotina_mensal() FROM PUBLIC,anon,authenticated;
DO $do$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.financeiro_operar(text,jsonb,uuid)'::regprocedure) INTO f;
f=replace(f,$s$IF _acao='config' THEN$s$,$s$IF _acao='config' THEN IF coalesce(trim(_dados->>'mensagem'),'')='' THEN RAISE EXCEPTION 'Informe o modelo da mensagem';END IF;$s$);
f=replace(f,$s$IF v<=0 OR d>hoje THEN$s$,$s$IF v IS NULL OR d IS NULL OR v<=0 OR d>hoje THEN$s$);
f=replace(f,$s$selecionadas=_dados->'alocacoes';$s$,$s$selecionadas=_dados->'alocacoes';IF selecionadas IS NOT NULL AND (SELECT count(*)<>count(DISTINCT z->>'id') FROM jsonb_array_elements(selecionadas) z) THEN RAISE EXCEPTION 'Uma cobrança não pode ser selecionada duas vezes';END IF;$s$);
f=replace(f,$s$v_id=(_dados->>'id')::uuid;motivo=trim$s$,$s$v_id=(_dados->>'id')::uuid;motivo=trim$s$);
f=replace(f,$s$IF r.estornado THEN RAISE EXCEPTION 'Pagamento já estornado';END IF;$s$,$s$IF r.estornado THEN RAISE EXCEPTION 'Pagamento já estornado';END IF;FOR x IN SELECT to_jsonb(p.data) FROM public.financeiro_pagamentos p WHERE p.residente_id=r.residente_id AND NOT p.estornado AND p.data>=r.data LOOP PERFORM private.financeiro_travar_data((x#>>'{}')::date);END LOOP;$s$);
f=replace(f,$s$ELSIF _acao='contato' THEN INSERT$s$,$s$ELSIF _acao='contato' THEN IF nullif(_dados->>'promessa_data','')::date<hoje THEN RAISE EXCEPTION 'A promessa deve ser para hoje ou uma data futura';END IF;INSERT$s$);
f=replace(f,$s$IF cfg.extras_agrupados THEN$s$,$s$IF cfg.extras_agrupados AND NOT coalesce((_dados->>'avulso')::boolean,false) THEN$s$);
f=replace(f,$s$d=(_dados->>'data')::date;PERFORM private.financeiro_travar_data(d);$s$,$s$d=(_dados->>'data')::date;IF d>hoje THEN RAISE EXCEPTION 'Data de lançamento não pode ser futura';END IF;PERFORM private.financeiro_travar_data(d);$s$);
EXECUTE f;
SELECT pg_get_functiondef('private.financeiro_saldo(uuid,date)'::regprocedure) INTO f;
f=replace(f,'multa numeric=0;','multa numeric=0; aplicada boolean=false;');f=replace(f,'IF multa=0 AND principal>0 THEN multa=round(principal*c.multa_bp::numeric/10000); END IF;','IF NOT aplicada THEN multa=round(principal*c.multa_bp::numeric/10000);aplicada=true; END IF;');EXECUTE f;END $do$;
CREATE FUNCTION private.financeiro_checar_registro() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF TG_TABLE_NAME='financeiro_pagamentos' AND NEW.forma='credito' AND NEW.fonte_credito IS NULL THEN RETURN NEW; END IF;RETURN NEW;END; $$;
REVOKE ALL ON FUNCTION private.financeiro_checar_registro() FROM PUBLIC,anon,authenticated;
ALTER TABLE public.financeiro_cadastros ADD CONSTRAINT financeiro_forma_preferida CHECK(forma_preferencial IN ('pix','dinheiro','transferencia','boleto','cartao','cheque'));
ALTER TABLE public.financeiro_itens ADD CONSTRAINT financeiro_categoria_item CHECK(categoria IN ('mensalidade','dieta_suplemento','higiene','bordado','outros'));
ALTER TABLE public.financeiro_abatimentos ADD CONSTRAINT financeiro_abatimentos_positivos CHECK(multa_centavos>=0 AND juros_centavos>=0 AND correcao_centavos>=0);
CREATE FUNCTION public.financeiro_contar_alertas() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE n integer;hoje date=(now() AT TIME ZONE 'America/Sao_Paulo')::date;BEGIN IF NOT private.financeiro_autorizado() THEN RETURN 0;END IF;SELECT count(*) INTO n FROM public.financeiro_cobrancas c WHERE NOT c.cancelada AND (private.financeiro_saldo(c.id,hoje)->>'saldo')::bigint>0 AND (c.vencimento<=hoje+coalesce((SELECT alerta_dias FROM public.financeiro_config WHERE id),3) OR (SELECT promessa_data FROM public.financeiro_contatos WHERE cobranca_id=c.id ORDER BY criado_em DESC LIMIT 1)<hoje);RETURN n;END; $$;
REVOKE ALL ON FUNCTION public.financeiro_contar_alertas() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.financeiro_contar_alertas() TO authenticated;